/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: blend565
 *
 * Description:
 *   Alpha blend src over dst, alpha 0..256.  Channels are unpacked first:
 *   interpolating the packed halfword directly would carry between fields.
 *
 ****************************************************************************/

static uint16_t blend565(uint16_t dst, uint16_t src, int32_t alpha)
{
  int32_t ia = 256 - alpha;
  int32_t r = (((src >> 11) & 0x1f) * alpha + ((dst >> 11) & 0x1f) * ia) >> 8;
  int32_t g = (((src >> 5) & 0x3f) * alpha + ((dst >> 5) & 0x3f) * ia) >> 8;
  int32_t b = ((src & 0x1f) * alpha + (dst & 0x1f) * ia) >> 8;

  return (uint16_t)((r << 11) | (g << 5) | b);
}

/****************************************************************************
 * Name: shade565
 *
 * Description:
 *   Scale a colour's channels by num/den.  Used for the iris gradient so the
 *   table only has to name one colour.
 *
 ****************************************************************************/

static uint16_t shade565(uint16_t c, int32_t num, int32_t den)
{
  int32_t r = (((c >> 11) & 0x1f) * num) / den;
  int32_t g = (((c >> 5) & 0x3f) * num) / den;
  int32_t b = ((c & 0x1f) * num) / den;

  if (r > 0x1f)
    {
      r = 0x1f;
    }

  if (g > 0x3f)
    {
      g = 0x3f;
    }

  if (b > 0x1f)
    {
      b = 0x1f;
    }

  return (uint16_t)((r << 11) | (g << 5) | b);
}

static void px_blend(struct canvas_s *cv, int x, int y, uint16_t colour,
                     int32_t alpha)
{
  uint16_t *p;

  if (alpha <= 0 || x < 0 || y < 0 || x >= cv->w || y >= cv->h)
    {
      return;
    }

  p = (uint16_t *)(void *)(cv->buf + (size_t)y * cv->stride) + x;
  *p = alpha >= 256 ? colour : blend565(*p, colour, alpha);
}

/****************************************************************************
 * Name: in_ellipse
 *
 * Description:
 *   dx^2/rx^2 + dy^2/ry^2 <= 1, cross-multiplied so there is no division.
 *   The products need 64 bits: dx and rx reach 160*16, so dx^2*ry^2 is about
 *   4.3e13.
 *
 ****************************************************************************/

static bool in_ellipse(int32_t dx, int32_t dy, int32_t rx, int32_t ry)
{
  int64_t a;
  int64_t b;

  if (rx <= 0 || ry <= 0)
    {
      return false;
    }

  a = (int64_t)dx * dx * ry * ry;
  b = (int64_t)dy * dy * rx * rx;

  return a + b <= (int64_t)rx * rx * ry * ry;
}

/****************************************************************************
 * Name: in_heart
 *
 * Description:
 *   (u^2 + v^2 - 1)^3 - u^2 v^3 <= 0 in 8.8 fixed point, with v measured
 *   upwards.  The 1.35 scale (346/256) is what makes the curve fill the
 *   requested bounding box; the shape sits slightly high in its box, so the
 *   caller shifts it down by ry/10.
 *
 ****************************************************************************/

static bool in_heart(int32_t dx, int32_t dy, int32_t rx, int32_t ry)
{
  int64_t u;
  int64_t v;
  int64_t t;

  if (rx <= 0 || ry <= 0)
    {
      return false;
    }

  u = ((int64_t)dx * 346) / rx;
  v = -((int64_t)dy * 346) / ry;
  t = u * u + v * v - 65536;

  return t * t * t - 256 * u * u * v * v * v <= 0;
}

static bool in_poly(const int16_t *pts, int npts, int32_t x, int32_t y)
{
  bool inside = false;
  int i;
  int j;

  for (i = 0, j = npts - 1; i < npts; j = i++)
    {
      int32_t xi = FPX(pts[2 * i]);
      int32_t yi = FPX(pts[2 * i + 1]);
      int32_t xj = FPX(pts[2 * j]);
      int32_t yj = FPX(pts[2 * j + 1]);
      int64_t lhs;
      int64_t rhs;
      bool    cross;

      if ((yi > y) == (yj > y))
        {
          continue;
        }

      /* x < xi + (xj - xi) * (y - yi) / (yj - yi), multiplied out so the
       * division disappears; the comparison flips when yj < yi.
       */

      lhs = (int64_t)(x - xi) * (yj - yi);
      rhs = (int64_t)(xj - xi) * (y - yi);
      cross = yj > yi ? lhs < rhs : lhs > rhs;

      if (cross)
        {
          inside = !inside;
        }
    }

  return inside;
}

/****************************************************************************
 * Name: prim_inside
 *
 * Description:
 *   The one predicate every shape funnels through.  x and y are subpixel
 *   absolute coordinates.
 *
 ****************************************************************************/

static bool prim_inside(const struct prim_s *p, int32_t x, int32_t y)
{
  int32_t dx = x - p->cx;
  int32_t dy = y - p->cy;

  switch (p->kind)
    {
      case PRIM_ELLIPSE:
        return in_ellipse(dx, dy, p->rx, p->ry);

      case PRIM_RING:
        return in_ellipse(dx, dy, p->rx, p->ry) &&
               !in_ellipse(dx, dy, p->rx - p->p0, p->ry - p->p0);

      case PRIM_ARC:
        {
          int64_t yc;

          if (dx < -p->rx || dx > p->rx || p->rx <= 0)
            {
              return false;
            }

          /* Parabola through (+-rx, cy) with its vertex p0 below cy. */

          yc = ((int64_t)p->p0 *
                ((int64_t)p->rx * p->rx - (int64_t)dx * dx)) /
               ((int64_t)p->rx * p->rx);

          return dy - yc <= p->p1 / 2 && yc - dy <= p->p1 / 2;
        }

      case PRIM_HEART:
        return in_heart(dx, dy, p->rx, p->ry);

      case PRIM_RRECT:
        {
          int32_t ax = dx < 0 ? -dx : dx;
          int32_t ay = dy < 0 ? -dy : dy;
          int32_t ox = ax - (p->rx - p->p0);
          int32_t oy = ay - (p->ry - p->p0);

          if (ax > p->rx || ay > p->ry)
            {
              return false;
            }

          if (ox <= 0 || oy <= 0)
            {
              return true;
            }

          return (int64_t)ox * ox + (int64_t)oy * oy <=
                 (int64_t)p->p0 * p->p0;
        }

      case PRIM_WAVE:
        {
          int32_t idx;
          int32_t yc;

          if (dx < -p->rx || dx > p->rx || p->rx <= 0)
            {
              return false;
            }

          idx = (int32_t)(((int64_t)(dx + p->rx) * 64 * p->p2) /
                          (2 * p->rx));
          yc = (p->p0 * g_sin64[idx & 63]) / 256;

          return dy - yc <= p->p1 / 2 && yc - dy <= p->p1 / 2;
        }

      case PRIM_POLY:
        return in_poly(p->pts, p->npts, x, y);

      default:
        return false;
    }
}

/****************************************************************************
 * Name: prim_draw
 *
 * Description:
 *   Scan the primitive's bounding box, take 3x3 subsamples per pixel and
 *   blend by coverage.  When c1 differs from c0 the colour is interpolated
 *   vertically across the box, which is how the iris gets its gradient.
 *
 ****************************************************************************/

static void prim_draw(struct canvas_s *cv, const struct prim_s *p,
                      uint16_t c0, uint16_t c1)
{
  int x0 = (int)((p->cx - p->rx) / FP) - 1;
  int x1 = (int)((p->cx + p->rx) / FP) + 1;
  int y0 = (int)((p->cy - p->ry) / FP) - 1;
  int y1 = (int)((p->cy + p->ry) / FP) + 1;
  int x;
  int y;

  if (x0 < 0)
    {
      x0 = 0;
    }

  if (y0 < 0)
    {
      y0 = 0;
    }

  if (x1 >= cv->w)
    {
      x1 = cv->w - 1;
    }

  if (y1 >= cv->h)
    {
      y1 = cv->h - 1;
    }

  for (y = y0; y <= y1; y++)
    {
      uint16_t colour = c0;

      if (c1 != c0 && y1 > y0)
        {
          colour = blend565(c0, c1, ((y - y0) * 256) / (y1 - y0));
        }

      for (x = x0; x <= x1; x++)
        {
          int cov = 0;
          int i;
          int j;

          for (j = 0; j < SUBN; j++)
            {
              for (i = 0; i < SUBN; i++)
                {
                  if (prim_inside(p, FPX(x) + g_sub_off[i],
                                  FPX(y) + g_sub_off[j]))
                    {
                      cov++;
                    }
                }
            }

          if (cov > 0)
            {
              px_blend(cv, x, y, colour, g_cov_alpha[cov]);
            }
        }
    }
}

/****************************************************************************
 * Name: draw_seg
 *
 * Description:
 *   Thick line segment with round caps: every point within thick/2 of the
 *   segment.  Distance is compared squared, so there is no square root.
 *
 ****************************************************************************/

static void draw_seg(struct canvas_s *cv, int32_t ax, int32_t ay,
                     int32_t bx, int32_t by, int32_t thick, uint16_t colour)
{
  int32_t r = thick / 2;
  int32_t dx = bx - ax;
  int32_t dy = by - ay;
  int64_t len2 = (int64_t)dx * dx + (int64_t)dy * dy;
  int32_t lo;
  int32_t hi;
  int x0;
  int x1;
  int y0;
  int y1;
  int x;
  int y;

  if (r <= 0)
    {
      return;
    }

  lo = ax < bx ? ax : bx;
  hi = ax > bx ? ax : bx;
  x0 = (int)((lo - r) / FP) - 1;
  x1 = (int)((hi + r) / FP) + 1;
  lo = ay < by ? ay : by;
  hi = ay > by ? ay : by;
  y0 = (int)((lo - r) / FP) - 1;
  y1 = (int)((hi + r) / FP) + 1;

  if (x0 < 0)
    {
      x0 = 0;
    }

  if (y0 < 0)
    {
      y0 = 0;
    }

  if (x1 >= cv->w)
    {
      x1 = cv->w - 1;
    }

  if (y1 >= cv->h)
    {
      y1 = cv->h - 1;
    }

  for (y = y0; y <= y1; y++)
    {
      for (x = x0; x <= x1; x++)
        {
          int cov = 0;
          int i;
          int j;

          for (j = 0; j < SUBN; j++)
            {
              for (i = 0; i < SUBN; i++)
                {
                  int32_t sx = FPX(x) + g_sub_off[i];
                  int32_t sy = FPX(y) + g_sub_off[j];
                  int32_t px = sx - ax;
                  int32_t py = sy - ay;
                  int64_t dot = (int64_t)px * dx + (int64_t)py * dy;
                  int64_t d2;

                  if (len2 == 0 || dot <= 0)
                    {
                      d2 = (int64_t)px * px + (int64_t)py * py;
                    }
                  else if (dot >= len2)
                    {
                      int32_t qx = sx - bx;
                      int32_t qy = sy - by;

                      d2 = (int64_t)qx * qx + (int64_t)qy * qy;
                    }
                  else
                    {
                      int64_t cr = (int64_t)px * dy - (int64_t)py * dx;

                      /* cr^2 / len2 <= r^2 without dividing. */

                      d2 = -1;
                      if (cr * cr <= (int64_t)r * r * len2)
                        {
                          cov++;
                        }
                    }

                  if (d2 >= 0 && d2 <= (int64_t)r * r)
                    {
                      cov++;
                    }
                }
            }

          if (cov > 0)
            {
              px_blend(cv, x, y, colour, g_cov_alpha[cov]);
            }
        }
    }
}

/****************************************************************************
 * Name: draw_blush
 *
 * Description:
 *   Soft radial patch: alpha falls off with the square of the radius, so the
 *   edge has no visible boundary.  A hard-edged circle here looks like a
 *   sticker rather than a cheek.
 *
 ****************************************************************************/

static void draw_blush(struct canvas_s *cv, int32_t cx, int32_t cy,
                       int32_t r, int32_t strength, uint16_t colour)
{
  int x0 = (int)((cx - r) / FP);
  int x1 = (int)((cx + r) / FP);
  int y0 = (int)((cy - r) / FP);
  int y1 = (int)((cy + r) / FP);
  int x;
  int y;

  if (strength <= 0 || r <= 0)
    {
      return;
    }

  for (y = y0; y <= y1; y++)
    {
      for (x = x0; x <= x1; x++)
        {
          int32_t dx = FPX(x) + FP / 2 - cx;
          int32_t dy = FPX(y) + FP / 2 - cy;
          int64_t d2 = (int64_t)dx * dx + (int64_t)dy * dy;
          int64_t r2 = (int64_t)r * r;
          int32_t alpha;

          if (d2 >= r2)
            {
              continue;
            }

          alpha = (int32_t)(((r2 - d2) * strength) / (r2 * 255 / 256));
          if (alpha > 256)
            {
              alpha = 256;
            }

          px_blend(cv, x, y, colour, alpha);
        }
    }
}

/****************************************************************************
 * Name: draw_tear
 *
 * Description:
 *   A drop is a circle with a tapered top, plus a specular dot.  Built from
 *   two primitives rather than its own implicit curve: reusing the ellipse
 *   and polygon predicates keeps the shape list short.
 *
 ****************************************************************************/

static void draw_tear(struct canvas_s *cv, int32_t cx, int32_t cy,
                      int32_t r, uint16_t colour)
{
  struct prim_s p;
  int16_t pts[6];

  memset(&p, 0, sizeof(p));

  /* Tapered top: a triangle from the drop's shoulders up to a point. */

  pts[0] = (int16_t)((cx - (r * 3) / 4) / FP);
  pts[1] = (int16_t)(cy / FP);
  pts[2] = (int16_t)((cx + (r * 3) / 4) / FP);
  pts[3] = (int16_t)(cy / FP);
  pts[4] = (int16_t)(cx / FP);
  pts[5] = (int16_t)((cy - r * 2) / FP);

  p.kind = PRIM_POLY;
  p.cx   = cx;
  p.cy   = cy - r;
  p.rx   = r + FP;
  p.ry   = r * 2 + FP;
  p.pts  = pts;
  p.npts = 3;
  prim_draw(cv, &p, colour, colour);

  memset(&p, 0, sizeof(p));
  p.kind = PRIM_ELLIPSE;
  p.cx   = cx;
  p.cy   = cy;
  p.rx   = r;
  p.ry   = r;
  prim_draw(cv, &p, colour, colour);

  /* Specular dot, offset up-left like the eye highlight. */

  memset(&p, 0, sizeof(p));
  p.kind = PRIM_ELLIPSE;
  p.cx   = cx - r / 3;
  p.cy   = cy - r / 3;
  p.rx   = r / 3;
  p.ry   = r / 3;
  prim_draw(cv, &p, C_WHITE, C_WHITE);
}

static void draw_spiral(struct canvas_s *cv, int32_t cx, int32_t cy,
                        int32_t r, int32_t phase, int32_t thick,
                        uint16_t colour)
{
  const int steps = 40;
  const int turns = 3;
  int32_t px = cx;
  int32_t py = cy;
  int i;

  for (i = 1; i <= steps; i++)
    {
      int32_t ang = phase + (i * turns * 256) / steps;
      int     si  = (ang & 255) >> 2;
      int32_t rr  = (r * i) / steps;
      int32_t nx  = cx + (rr * g_sin64[(si + 16) & 63]) / 256;
      int32_t ny  = cy + (rr * g_sin64[si & 63]) / 256;

      draw_seg(cv, px, py, nx, ny, thick, colour);
      px = nx;
      py = ny;
    }
}

static void draw_star(struct canvas_s *cv, int32_t cx, int32_t cy,
                      int32_t r, int32_t phase, uint16_t colour)
{
  struct prim_s p;
  int16_t pts[20];
  int i;

  for (i = 0; i < 10; i++)
    {
      int32_t ang = phase + (i * 256 + 5) / 10 - 64;
      int     si  = (ang & 255) >> 2;
      int32_t rr  = (i & 1) ? (r * 45) / 100 : r;

      pts[2 * i]     = (int16_t)((cx + (rr * g_sin64[(si + 16) & 63]) /
                                  256) / FP);
      pts[2 * i + 1] = (int16_t)((cy + (rr * g_sin64[si & 63]) / 256) / FP);
    }

  memset(&p, 0, sizeof(p));
  p.kind = PRIM_POLY;
  p.cx   = cx;
  p.cy   = cy;
  p.rx   = r + FP;
  p.ry   = r + FP;
  p.pts  = pts;
  p.npts = 10;
  prim_draw(cv, &p, colour, colour);
}

/****************************************************************************
 * Name: draw_eye
 *
 * Description:
 *   One eye.  cx is the eye centre in subpixels; mirror flips the shapes
 *   that are not left/right symmetric (the angry wedge and the specular
 *   highlight).
 *
 ****************************************************************************/

static void draw_eye(struct canvas_s *cv, const struct face_s *f,
                     int32_t cx, int32_t cy, int32_t lid, bool mirror)
{
  int32_t rx = FPX(f->eye_rx);
  int32_t ry = FPX(f->eye_ry);
  struct prim_s p;

  memset(&p, 0, sizeof(p));

  switch (f->eye_style)
    {
      case EYE_ROUND:
        {
          int32_t irisr = FPX(f->iris_r);
          int32_t pupr  = FPX(f->pupil_r);
          int32_t spec  = irisr / 3;

          p.kind = PRIM_ELLIPSE;
          p.cx = cx;
          p.cy = cy;
          p.rx = rx;
          p.ry = ry;
          prim_draw(cv, &p, f->sclera, f->sclera);

          if (irisr > 0)
            {
              p.rx = irisr;
              p.ry = irisr;
              prim_draw(cv, &p, f->iris, shade565(f->iris, 55, 100));
            }

          if (pupr > 0)
            {
              p.rx = pupr;
              p.ry = pupr;
              prim_draw(cv, &p, C_BLACK, C_BLACK);
            }

          if (spec > 0)
            {
              p.cx = cx + (mirror ? -irisr / 2 : irisr / 2);
              p.cy = cy - irisr / 2;
              p.rx = spec;
              p.ry = spec;
              prim_draw(cv, &p, C_WHITE, C_WHITE);
            }

          /* The lid is painted in the background colour, so its lower edge
           * is anti-aliased like any other shape -- a half-closed eye must
           * not show a stair-stepped horizontal cut.
           */

          if (lid > 0)
            {
              int32_t l = FPX(lid);

              if (l > 2 * ry)
                {
                  l = 2 * ry;
                }

              memset(&p, 0, sizeof(p));
              p.kind = PRIM_RRECT;
              p.rx   = rx + FP;
              p.ry   = l / 2;
              p.cx   = cx;
              p.cy   = cy - ry + p.ry;
              p.p0   = 0;
              prim_draw(cv, &p, f->bg, f->bg);

              /* Fully closed: leave a lash line behind, otherwise the eye
               * simply vanishes and the blink reads as a glitch.
               */

              if (l >= 2 * ry)
                {
                  draw_seg(cv, cx - rx, cy, cx + rx, cy,
                           FPX(4), f->fg);
                }
            }
        }
        break;

      case EYE_CURVE:
        p.kind = PRIM_ARC;
        p.cx   = cx;
        p.cy   = cy + FPX(f->eye_curve) / 2;
        p.rx   = rx;
        p.ry   = FPX(f->eye_curve) + FPX(8);
        p.p0   = -FPX(f->eye_curve);
        p.p1   = FPX(5);
        prim_draw(cv, &p, f->fg, f->fg);
        break;

      case EYE_LINE:
        p.kind = PRIM_RRECT;
        p.cx   = cx;
        p.cy   = cy;
        p.rx   = rx;
        p.ry   = FPX(3);
        p.p0   = FPX(3);
        prim_draw(cv, &p, f->fg, f->fg);
        break;

      case EYE_ANGRY:
        {
          int32_t inner = mirror ? cx - rx : cx + rx;
          int32_t outer = mirror ? cx + rx : cx - rx;

          draw_seg(cv, outer, cy - ry, inner, cy, FPX(5), f->fg);
          draw_seg(cv, outer, cy + ry, inner, cy, FPX(5), f->fg);
        }
        break;

      case EYE_X:
        draw_seg(cv, cx - rx, cy - ry, cx + rx, cy + ry, FPX(5), f->fg);
        draw_seg(cv, cx + rx, cy - ry, cx - rx, cy + ry, FPX(5), f->fg);
        break;

      case EYE_HEART:
        p.kind = PRIM_HEART;
        p.cx   = cx;
        p.cy   = cy + ry / 10;
        p.rx   = rx;
        p.ry   = ry;
        prim_draw(cv, &p, f->iris, shade565(f->iris, 60, 100));
        break;

      case EYE_STAR:
        draw_star(cv, cx, cy, rx, f->spin, f->iris);
        break;

      case EYE_SPIRAL:
        draw_spiral(cv, cx, cy, rx, f->spin, FPX(4), f->fg);
        break;

      default:
        break;
    }
}

static void draw_mouth(struct canvas_s *cv, const struct face_s *f)
{
  int32_t cx = FPX(cv->w / 2);
  int32_t cy = FPX(f->mouth_y);
  int32_t hw = FPX(f->mouth_w) / 2;
  int32_t th = FPX(f->mouth_thick);
  struct prim_s p;

  memset(&p, 0, sizeof(p));

  switch (f->mouth_style)
    {
      case MOUTH_ARC:
        p.kind = PRIM_ARC;
        p.cx   = cx;
        p.cy   = cy;
        p.rx   = hw;
        p.ry   = FPX(f->mouth_curve < 0 ? -f->mouth_curve :
                     f->mouth_curve) + th;
        p.p0   = FPX(f->mouth_curve);
        p.p1   = th;
        prim_draw(cv, &p, f->fg, f->fg);
        break;

      case MOUTH_LINE:
        p.kind = PRIM_RRECT;
        p.cx   = cx;
        p.cy   = cy;
        p.rx   = hw;
        p.ry   = th / 2;
        p.p0   = th / 2;
        prim_draw(cv, &p, f->fg, f->fg);
        break;

      case MOUTH_O:
        p.kind = PRIM_RING;
        p.cx   = cx;
        p.cy   = cy;
        p.rx   = hw;
        p.ry   = FPX(f->mouth_open) / 2;
        p.p0   = th;
        prim_draw(cv, &p, f->fg, f->fg);
        break;

      case MOUTH_OPEN:
        {
          int32_t oh = FPX(f->mouth_open) / 2;

          p.kind = PRIM_ELLIPSE;
          p.cx   = cx;
          p.cy   = cy;
          p.rx   = hw;
          p.ry   = oh;
          prim_draw(cv, &p, f->mouth_fill, shade565(f->mouth_fill, 60, 100));

          p.kind = PRIM_RING;
          p.p0   = th / 2;
          prim_draw(cv, &p, f->fg, f->fg);

          /* Teeth: a band across the top of the cavity.  Without it a wide
           * open mouth reads as a hole rather than a laugh.
           */

          if (oh > FPX(6))
            {
              p.kind = PRIM_RRECT;
              p.cx   = cx;
              p.cy   = cy - oh + th / 2 + FPX(3);
              p.rx   = (hw * 7) / 10;
              p.ry   = FPX(3);
              p.p0   = FPX(2);
              prim_draw(cv, &p, C_WHITE, C_WHITE);
            }

          if (f->tongue > 0)
            {
              p.kind = PRIM_ELLIPSE;
              p.cx   = cx;
              p.cy   = cy + oh - FPX(f->tongue) / 2;
              p.rx   = hw / 2;
              p.ry   = FPX(f->tongue) / 2;
              p.p0   = 0;
              prim_draw(cv, &p, C_PINK, shade565(C_PINK, 70, 100));
            }
        }
        break;

      case MOUTH_TEETH:
        {
          int32_t oh = FPX(f->mouth_open) / 2;
          int i;

          p.kind = PRIM_RRECT;
          p.cx   = cx;
          p.cy   = cy;
          p.rx   = hw;
          p.ry   = oh;
          p.p0   = FPX(3);
          prim_draw(cv, &p, f->fg, f->fg);

          p.rx = hw - FPX(2);
          p.ry = oh - FPX(2);
          p.p0 = FPX(2);
          prim_draw(cv, &p, C_WHITE, C_WHITE);

          for (i = -2; i <= 2; i++)
            {
              int32_t x = cx + (i * hw) / 3;

              draw_seg(cv, x, cy - oh, x, cy + oh, FPX(2), f->fg);
            }

          draw_seg(cv, cx - hw, cy, cx + hw, cy, FPX(2), f->fg);
        }
        break;

      case MOUTH_WAVE:
        p.kind = PRIM_WAVE;
        p.cx   = cx;
        p.cy   = cy;
        p.rx   = hw;
        p.ry   = FPX(f->mouth_open < 0 ? -f->mouth_open : f->mouth_open) +
                 th;
        p.p0   = FPX(f->mouth_open);
        p.p1   = th;
        p.p2   = 2;
        prim_draw(cv, &p, f->fg, f->fg);
        break;

      default:
        break;
    }
}

static void face_render_one(struct canvas_s *cv, const struct face_s *f)
{
  int32_t cxc = FPX(cv->w / 2);
  int32_t eyl = cxc - FPX(f->eye_dx);
  int32_t eyr = cxc + FPX(f->eye_dx);
  int32_t eyy = FPX(f->eye_y);
  int     y;

  /* Background.  The glass is round, so the corners of this rectangle are
   * behind the bezel and cost nothing to fill.
   */

  for (y = 0; y < cv->h; y++)
    {
      uint16_t *row = (uint16_t *)(void *)(cv->buf + (size_t)y * cv->stride);
      int x;

      for (x = 0; x < cv->w; x++)
        {
          row[x] = f->bg;
        }
    }

  if (f->blush > 0)
    {
      draw_blush(cv, eyl - FPX(10), FPX(f->mouth_y) - FPX(14), FPX(15),
                 f->blush, C_PINK);
      draw_blush(cv, eyr + FPX(10), FPX(f->mouth_y) - FPX(14), FPX(15),
                 f->blush, C_PINK);
    }

  draw_eye(cv, f, eyl, eyy, f->lid_l, false);
  draw_eye(cv, f, eyr, eyy, f->lid_r, true);

  if (f->brow_len > 0)
    {
      int32_t hl = FPX(f->brow_len) / 2;
      int32_t ti = FPX(f->brow_tilt);
      int32_t by = FPX(f->brow_y);
      int32_t bt = FPX(f->brow_thick);

      draw_seg(cv, eyl - hl, by - ti, eyl + hl, by + ti, bt, f->fg);
      draw_seg(cv, eyr + hl, by - ti, eyr - hl, by + ti, bt, f->fg);
    }

  draw_mouth(cv, f);

  if (f->tear > 0)
    {
      /* Fall from just below the eye to the lower cheek.  The end point is
       * kept at y=128 so the drop stays inside the round glass: at y=150 the
       * visible half-width is only 38px and the eye columns are outside it.
       */

      int32_t ty = eyy + FPX(f->eye_ry) + ((FPX(128) - eyy -
                   FPX(f->eye_ry)) * f->tear) / 1000;

      draw_tear(cv, eyl, ty, FPX(5), C_TEAR);
      draw_tear(cv, eyr, ty, FPX(5), C_TEAR);
    }
}

/****************************************************************************
 * Name: face_lerp
 *
 * Description:
 *   Interpolate the numeric block between two keyframes.  Styles and colours
 *   are taken from a: an enum has no meaningful midpoint, and interpolating
 *   packed RGB565 would carry between channels.
 *
 *   The block is walked as an int16_t array so that a field added to
 *   struct face_s between eye_dx and fg is animated without touching this
 *   function.  test_face.c checks that every field in the range moves.
 *
 ****************************************************************************/

static void face_lerp(struct face_s *out, const struct face_s *a,
                      const struct face_s *b, int32_t num, int32_t den)
{
  const int16_t *pa = (const int16_t *)(const void *)
                      ((const uint8_t *)a + FACE_NUM_OFF);
  const int16_t *pb = (const int16_t *)(const void *)
                      ((const uint8_t *)b + FACE_NUM_OFF);
  int16_t *po;
  size_t i;

  *out = *a;
  po = (int16_t *)(void *)((uint8_t *)out + FACE_NUM_OFF);

  if (den <= 0)
    {
      return;
    }

  for (i = 0; i < FACE_NUM_COUNT; i++)
    {
      po[i] = (int16_t)(pa[i] + ((int32_t)(pb[i] - pa[i]) * num) / den);
    }
}

static uint32_t expr_duration(const struct expression_s *e)
{
  uint32_t total = 0;
  int i;

  if (e->nkeys < 2)
    {
      return 0;
    }

  for (i = 0; i < e->nkeys; i++)
    {
      total += e->keys[i].hold_ms;
    }

  return total;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int preview_face_count(void)
{
  return EXPR_COUNT;
}

const char *preview_face_name(int idx)
{
  if (idx < 0 || idx >= EXPR_COUNT)
    {
      return NULL;
    }

  return g_expr[idx].name;
}

int preview_face_lookup(const char *name)
{
  int i;

  if (name == NULL)
    {
      return -1;
    }

  for (i = 0; i < EXPR_COUNT; i++)
    {
      if (strcmp(g_expr[i].name, name) == 0)
        {
          return i;
        }
    }

  return -1;
}

uint32_t preview_face_duration_ms(int idx)
{
  if (idx < 0 || idx >= EXPR_COUNT)
    {
      return 0;
    }

  return expr_duration(&g_expr[idx]);
}

void preview_face_render(uint8_t *buf, size_t stride, int w, int h,
                         int idx, uint32_t phase_ms)
{
  const struct expression_s *e;
  struct canvas_s cv;
  struct face_s f;
  uint32_t total;
  uint32_t t;
  int i;

  if (buf == NULL || w <= 0 || h <= 0 || idx < 0 || idx >= EXPR_COUNT)
    {
      return;
    }

  e = &g_expr[idx];
  cv.buf    = buf;
  cv.stride = stride;
  cv.w      = w;
  cv.h      = h;

  total = expr_duration(e);
  if (total == 0)
    {
      f = e->keys[0].f;
    }
  else
    {
      t = phase_ms % total;

      for (i = 0; i < e->nkeys; i++)
        {
          uint32_t hold = e->keys[i].hold_ms;

          if (t < hold || i == e->nkeys - 1)
            {
              const struct face_s *nxt =
                &e->keys[(i + 1) % e->nkeys].f;

              face_lerp(&f, &e->keys[i].f, nxt, (int32_t)t,
                        (int32_t)(hold == 0 ? 1 : hold));
              break;
            }

          t -= hold;
        }
    }

  if ((e->flags & FACE_SPIN) != 0)
    {
      /* A spiral or star has no meaningful midpoint to interpolate towards
       * across the loop's wrap-around, so its rotation is driven straight
       * from the phase instead of from keyframes.
       */

      f.spin = (int16_t)((f.spin + (int32_t)(phase_ms / 4)) & 255);
    }

  face_render_one(&cv, &f);
}

/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_face.c
 *
 * Desktop tests for the camera_preview expression renderer.
 *
 * The renderer is pure integer code writing RGB565 into caller memory, so
 * the entire expression table can be rendered and inspected here.  That is
 * the point of keeping it free of V4L2/fb dependencies: a wrong sign in a
 * curvature, a mirrored coordinate, or a shape that spills outside the round
 * glass costs one second here instead of a four-minute flash cycle.
 *
 * The source is #included rather than linked so the tests can reach the
 * static expression table and face_lerp().
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "preview_face.c"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TW      160
#define TH      160
#define TSTRIDE (TW * 2)
#define GUARD   64
#define GUARDV  0xa5

#define CHECK(cond, msg)                                                   \
  do                                                                       \
    {                                                                      \
      if (!(cond))                                                         \
        {                                                                  \
          printf("FAIL: %s (%s:%d)\n", (msg), __FILE__, __LINE__);         \
          g_failures++;                                                    \
        }                                                                  \
    }                                                                      \
  while (0)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_failures;
static uint8_t g_mem[GUARD + TH * TSTRIDE + GUARD];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint8_t *fbuf(void)
{
  return g_mem + GUARD;
}

static void render(int idx, uint32_t phase)
{
  memset(g_mem, GUARDV, sizeof(g_mem));
  preview_face_render(fbuf(), TSTRIDE, TW, TH, idx, phase);
}

static bool guards_intact(void)
{
  size_t i;

  for (i = 0; i < GUARD; i++)
    {
      if (g_mem[i] != GUARDV)
        {
          return false;
        }

      if (g_mem[GUARD + TH * TSTRIDE + i] != GUARDV)
        {
          return false;
        }
    }

  return true;
}

static uint16_t px(int x, int y)
{
  const uint16_t *row = (const uint16_t *)(const void *)
                        (fbuf() + (size_t)y * TSTRIDE);

  return row[x];
}

static uint16_t face_bg(int idx)
{
  return g_expr[idx].keys[0].f.bg;
}

/* Number of pixels differing from the background inside a box. */

static int count_fg(int idx, int x0, int y0, int x1, int y1)
{
  uint16_t bg = face_bg(idx);
  int n = 0;
  int x;
  int y;

  for (y = y0; y <= y1; y++)
    {
      for (x = x0; x <= x1; x++)
        {
          if (px(x, y) != bg)
            {
              n++;
            }
        }
    }

  return n;
}

/****************************************************************************
 * Name: test_every_frame_stays_in_bounds
 *
 * Description:
 *   Renders every expression at several phases and checks the sentinel
 *   regions on both sides of the framebuffer.  A shape whose bounding box is
 *   computed wrong writes outside the buffer, which on the board would
 *   corrupt whatever the kernel heap put next to the framebuffer rather than
 *   showing up as a drawing artefact.
 *
 ****************************************************************************/

static void test_every_frame_stays_in_bounds(void)
{
  int idx;

  for (idx = 0; idx < preview_face_count(); idx++)
    {
      uint32_t dur = preview_face_duration_ms(idx);
      uint32_t step = dur ? dur / 8 + 1 : 137;
      uint32_t t;

      for (t = 0; t < (dur ? dur : 1); t += step)
        {
          render(idx, t);
          CHECK(guards_intact(), preview_face_name(idx));
        }
    }
}

/****************************************************************************
 * Name: test_elements_stay_inside_round_glass
 *
 * Description:
 *   The panel is round: only the inscribed circle r=80 is visible.  Any
 *   non-background pixel outside it is work whose result is behind the
 *   bezel, and usually means a coordinate was authored for a square screen.
 *
 ****************************************************************************/

static void test_elements_stay_inside_round_glass(void)
{
  int idx;

  for (idx = 0; idx < preview_face_count(); idx++)
    {
      uint32_t dur = preview_face_duration_ms(idx);
      uint32_t step = dur ? dur / 6 + 1 : 211;
      uint32_t t;

      for (t = 0; t < (dur ? dur : 1); t += step)
        {
          uint16_t bg = face_bg(idx);
          int worst = 0;
          int x;
          int y;

          render(idx, t);

          for (y = 0; y < TH; y++)
            {
              for (x = 0; x < TW; x++)
                {
                  int dx;
                  int dy;
                  int d2;

                  if (px(x, y) == bg)
                    {
                      continue;
                    }

                  dx = 2 * x + 1 - TW;   /* twice the offset from centre */
                  dy = 2 * y + 1 - TH;
                  d2 = dx * dx + dy * dy;

                  if (d2 > worst)
                    {
                      worst = d2;
                    }
                }
            }

          /* (2*80)^2 = 25600 in the doubled units used above. */

          CHECK(worst <= 25600, preview_face_name(idx));
        }
    }
}

/****************************************************************************
 * Name: test_lid_closes_the_eye
 *
 * Description:
 *   blink's third keyframe has the lid at its full travel.  The eye box must
 *   then be nearly empty -- only the lash line survives.  A lid that paints
 *   the wrong rectangle, or a travel that stops short of 2*eye_ry, leaves a
 *   sliver of sclera and the blink looks like a flicker.
 *
 ****************************************************************************/

static void test_lid_closes_the_eye(void)
{
  int idx = preview_face_lookup("blink");
  int open_px;
  int shut_px;

  CHECK(idx >= 0, "blink must exist");
  if (idx < 0)
    {
      return;
    }

  render(idx, 0);
  open_px = count_fg(idx, 26, 36, 74, 88);

  render(idx, 875);         /* inside the closed segment */
  shut_px = count_fg(idx, 26, 36, 74, 88);

  CHECK(open_px > 400, "open eye should cover the box");
  CHECK(shut_px * 4 < open_px, "closed eye must be nearly empty");
  CHECK(shut_px > 0, "closed eye should still show a lash line");
}

/****************************************************************************
 * Name: test_mouth_curvature_sign
 *
 * Description:
 *   smile's mouth must bow downwards at the centre and sad's upwards.  This
 *   is the one place where a sign error produces a face that is perfectly
 *   drawn and completely wrong.
 *
 ****************************************************************************/

static void test_mouth_curvature_sign(void)
{
  int smile = preview_face_lookup("smile");
  int sad = preview_face_lookup("sad");
  int smile_y = -1;
  int sad_y = -1;
  int y;

  CHECK(smile >= 0 && sad >= 0, "smile and sad must exist");
  if (smile < 0 || sad < 0)
    {
      return;
    }

  render(smile, 0);
  for (y = 90; y < 150; y++)
    {
      if (px(TW / 2, y) != face_bg(smile))
        {
          smile_y = y;
          break;
        }
    }

  render(sad, 0);
  for (y = 90; y < 150; y++)
    {
      if (px(TW / 2, y) != face_bg(sad))
        {
          sad_y = y;
          break;
        }
    }

  CHECK(smile_y > 0 && sad_y > 0, "both mouths must appear near the centre");
  CHECK(smile_y > sad_y, "smile centre must sit below sad centre");
}

/****************************************************************************
 * Name: test_left_right_symmetry
 *
 * Description:
 *   Every expression except the two rotating ones is mirror symmetric, and
 *   wink deliberately is not.  Mirroring bugs are easy to introduce (the
 *   specular highlight and the angry wedge both flip) and hard to see on a
 *   160x160 panel.
 *
 ****************************************************************************/

static void test_left_right_symmetry(void)
{
  static const char *symmetric[] =
  {
    "neutral", "smile", "grin", "sad", "angry", "surprise", "meh",
    "tongue", "laughcry", "blink", "sleepy", "ko", "love"
  };

  size_t i;

  for (i = 0; i < sizeof(symmetric) / sizeof(symmetric[0]); i++)
    {
      int idx = preview_face_lookup(symmetric[i]);
      int bad = 0;
      int x;
      int y;

      CHECK(idx >= 0, symmetric[i]);
      if (idx < 0)
        {
          continue;
        }

      render(idx, preview_face_duration_ms(idx) / 3);

      for (y = 0; y < TH; y++)
        {
          for (x = 0; x < TW / 2; x++)
            {
              if (px(x, y) != px(TW - 1 - x, y))
                {
                  bad++;
                }
            }
        }

      CHECK(bad == 0, symmetric[i]);
    }

  /* wink closes one eye only. */

  {
    int idx = preview_face_lookup("wink");
    int bad = 0;
    int x;
    int y;

    CHECK(idx >= 0, "wink must exist");
    if (idx >= 0)
      {
        render(idx, 900);

        for (y = 0; y < TH; y++)
          {
            for (x = 0; x < TW / 2; x++)
              {
                if (px(x, y) != px(TW - 1 - x, y))
                  {
                    bad++;
                  }
              }
          }

        CHECK(bad > 100, "wink must be asymmetric while winking");
      }
  }
}

/****************************************************************************
 * Name: test_antialiasing_produces_edge_shades
 *
 * Description:
 *   Without anti-aliasing every pixel is one of the palette colours.  This
 *   counts pixels that are none of them, i.e. real coverage blends.
 *
 ****************************************************************************/

static void test_antialiasing_produces_edge_shades(void)
{
  int idx = preview_face_lookup("neutral");
  const struct face_s *f;
  int blends = 0;
  int x;
  int y;

  CHECK(idx >= 0, "neutral must exist");
  if (idx < 0)
    {
      return;
    }

  f = &g_expr[idx].keys[0].f;
  render(idx, 0);

  for (y = 0; y < TH; y++)
    {
      for (x = 0; x < TW; x++)
        {
          uint16_t c = px(x, y);

          if (c != f->bg && c != f->sclera && c != f->iris &&
              c != f->fg && c != C_BLACK && c != C_WHITE)
            {
              blends++;
            }
        }
    }

  CHECK(blends > 50, "edges should carry intermediate shades");
}

/****************************************************************************
 * Name: test_animations_actually_move
 *
 * Description:
 *   Every animated expression must differ between phases.  A keyframe field
 *   that is not interpolated, or a duration of zero, shows up here as a
 *   still image.
 *
 ****************************************************************************/

static void test_animations_actually_move(void)
{
  int idx;

  for (idx = 0; idx < preview_face_count(); idx++)
    {
      uint32_t dur = preview_face_duration_ms(idx);
      static uint16_t first[TH][TW];
      int diff = 0;
      int x;
      int y;

      if (dur == 0)
        {
          continue;
        }

      render(idx, 0);
      for (y = 0; y < TH; y++)
        {
          for (x = 0; x < TW; x++)
            {
              first[y][x] = px(x, y);
            }
        }

      render(idx, dur / 2);
      for (y = 0; y < TH; y++)
        {
          for (x = 0; x < TW; x++)
            {
              if (first[y][x] != px(x, y))
                {
                  diff++;
                }
            }
        }

      CHECK(diff > 0, preview_face_name(idx));
    }
}

/****************************************************************************
 * Name: test_phase_wraps_cleanly
 *
 * Description:
 *   phase_ms is a free-running millisecond counter in the caller, so
 *   render(t) and render(t + duration) must agree.  The two FACE_SPIN
 *   expressions are excluded: their rotation is driven from the raw phase
 *   precisely because it cannot wrap through the keyframe list.
 *
 ****************************************************************************/

static void test_phase_wraps_cleanly(void)
{
  int idx;

  for (idx = 0; idx < preview_face_count(); idx++)
    {
      uint32_t dur = preview_face_duration_ms(idx);
      static uint16_t base[TH][TW];
      int diff = 0;
      int x;
      int y;

      if (dur == 0 || (g_expr[idx].flags & FACE_SPIN) != 0)
        {
          continue;
        }

      render(idx, 17);
      for (y = 0; y < TH; y++)
        {
          for (x = 0; x < TW; x++)
            {
              base[y][x] = px(x, y);
            }
        }

      render(idx, 17 + dur);
      for (y = 0; y < TH; y++)
        {
          for (x = 0; x < TW; x++)
            {
              if (base[y][x] != px(x, y))
                {
                  diff++;
                }
            }
        }

      CHECK(diff == 0, preview_face_name(idx));
    }
}

/****************************************************************************
 * Name: test_lerp_covers_every_numeric_field
 *
 * Description:
 *   face_lerp() walks the block between eye_dx and fg as an int16_t array so
 *   that new fields animate without editing it.  This pins the field count
 *   down: if it changes, whoever added the field has to confirm the field
 *   belongs inside the interpolated range rather than outside it.
 *
 ****************************************************************************/

static void test_lerp_covers_every_numeric_field(void)
{
  struct face_s a;
  struct face_s b;
  struct face_s mid;
  const int16_t *pm;
  size_t i;
  int wrong = 0;

  CHECK(FACE_NUM_COUNT == 22,
        "interpolated field count changed -- check the new field belongs "
        "between eye_dx and fg");

  memset(&a, 0, sizeof(a));
  memset(&b, 0, sizeof(b));
  a.eye_style = EYE_ROUND;
  b.eye_style = EYE_STAR;
  a.fg = C_WHITE;
  b.fg = C_RED;

  {
    int16_t *pb = (int16_t *)(void *)((uint8_t *)&b + FACE_NUM_OFF);

    for (i = 0; i < FACE_NUM_COUNT; i++)
      {
        pb[i] = 100;
      }
  }

  face_lerp(&mid, &a, &b, 1, 2);
  pm = (const int16_t *)(const void *)((const uint8_t *)&mid +
                                       FACE_NUM_OFF);

  for (i = 0; i < FACE_NUM_COUNT; i++)
    {
      if (pm[i] != 50)
        {
          wrong++;
        }
    }

  CHECK(wrong == 0, "every numeric field must interpolate");
  CHECK(mid.eye_style == EYE_ROUND, "style must snap to the first keyframe");
  CHECK(mid.fg == C_WHITE, "colour must snap to the first keyframe");
}

/****************************************************************************
 * Name: test_table_lookup
 ****************************************************************************/

static void test_table_lookup(void)
{
  int idx;
  int statics = 0;
  int animated = 0;

  CHECK(preview_face_count() == 16, "expression count");
  CHECK(preview_face_lookup("nosuchface") == -1, "unknown name must fail");
  CHECK(preview_face_lookup(NULL) == -1, "NULL name must fail");
  CHECK(preview_face_name(-1) == NULL, "negative index must fail");
  CHECK(preview_face_name(preview_face_count()) == NULL,
        "index past the end must fail");

  for (idx = 0; idx < preview_face_count(); idx++)
    {
      const char *name = preview_face_name(idx);

      CHECK(name != NULL, "name must exist");
      CHECK(preview_face_lookup(name) == idx, "lookup must round-trip");

      if (preview_face_duration_ms(idx) == 0)
        {
          statics++;
        }
      else
        {
          animated++;
        }
    }

  CHECK(statics == 8, "eight static expressions");
  CHECK(animated == 8, "eight animated expressions");
  CHECK(preview_face_lookup("laughcry") >= 0, "laughcry must exist");
}

/****************************************************************************
 * Name: test_render_rejects_bad_input
 ****************************************************************************/

static void test_render_rejects_bad_input(void)
{
  memset(g_mem, GUARDV, sizeof(g_mem));

  preview_face_render(NULL, TSTRIDE, TW, TH, 0, 0);
  preview_face_render(fbuf(), TSTRIDE, 0, TH, 0, 0);
  preview_face_render(fbuf(), TSTRIDE, TW, TH, -1, 0);
  preview_face_render(fbuf(), TSTRIDE, TW, TH, preview_face_count(), 0);

  CHECK(guards_intact(), "bad input must not write anything");

  {
    size_t i;
    int touched = 0;

    for (i = 0; i < (size_t)(TH * TSTRIDE); i++)
      {
        if (fbuf()[i] != GUARDV)
          {
            touched++;
          }
      }

    CHECK(touched == 0, "bad input must leave the buffer alone");
  }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(void)
{
  test_table_lookup();
  test_render_rejects_bad_input();
  test_every_frame_stays_in_bounds();
  test_elements_stay_inside_round_glass();
  test_lid_closes_the_eye();
  test_mouth_curvature_sign();
  test_left_right_symmetry();
  test_antialiasing_produces_edge_shades();
  test_animations_actually_move();
  test_phase_wraps_cleanly();
  test_lerp_covers_every_numeric_field();

  if (g_failures != 0)
    {
      printf("test_face: %d failure(s)\n", g_failures);
      return EXIT_FAILURE;
    }

  printf("PASS: all preview_face.c tests passed\n");
  return EXIT_SUCCESS;
}

