/****************************************************************************
 * Name: bk7258_start_boot_greeting
 *
 * Description:
 *   Starts the 'hello' builtin, which writes the greeting onto the panels one
 *   pen stroke at a time.  Returns a negative errno when it could not be
 *   started, in which case the caller draws the static greeting instead.
 *
 *   exec_builtin() is declared locally rather than by including the
 *   application header: this is board code and has no business depending on
 *   apps/ headers.  The symbol only exists when the app is in the build,
 *   which is exactly the condition the caller is compiled under.
 *
 *   hold=0 means the task exits as soon as the word is written, so nothing
 *   lingers; the pixels stay on the panel because nobody else draws.
 *
 ****************************************************************************/

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_264_HELLO_SCREEN
struct nsh_param_s;
int exec_builtin(const char *appname, char * const *argv,
                 const struct nsh_param_s *param);

static int bk7258_start_boot_greeting(void)
{
  static char * const argv[] =
  {
    "hello", "ms=1200", "hold=0", NULL
  };

  int pid = exec_builtin("hello", argv, NULL);

  if (pid < 0)
    {
      printf("fb: boot greeting animation not started: %d\n", pid);
      return -errno;
    }

  printf("fb: boot greeting animation started (pid %d)\n", pid);
  return OK;
}
#else
static int bk7258_start_boot_greeting(void)
{
  return -ENOTSUP;
}
#endif

